    # trade-derived'ы (YoY %, QoQ %) теперь доступны через in-page
    # ViewModePicker на странице родителя (exports / imports). В каталоге
    # их прячем — это **режимы отображения**, а не отдельные карточки.
    "exports-yoy",
    "exports-qoq",
